'use strict';

/**
* Compute the range of a one-dimensional single-precision floating-point ndarray.
*
* @module @stdlib/stats/base/ndarray/srange
*
* @example
* import Float32Vector from '@stdlib/ndarray/vector/float32';
* import srange from '@stdlib/stats/base/ndarray/srange';
*
* var x = new Float32Vector( [ 1.0, 3.0, 4.0, 2.0 ] );
*
* var v = srange( [ x ] );
* // returns 3.0
*/

// MODULES //

var join = require( 'path' ).join;
import tryRequire from '@stdlib/utils/try-require';
import isError from '@stdlib/assert/is-error';
import main from './main.js';


// MAIN //

var srange;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	srange = main;
} else {
	srange = tmp;
}


// EXPORTS //

export default srange;
